$ErrorActionPreference='Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))
. (Join-Path $repo 'tools/Invoke-ArenaSourceChecks.ps1')
$teleport=Join-Path $repo 'ArenaMode.Client/Combat/Translocator/ArenaTranslocatorTeleport.cs'
$gate=Join-Path $repo 'ArenaMode.Client/Areas/ArenaAreaTranslocatorGate.cs'
$faults=@(
    @{Name='missing-native-authorization-hook';Path=(Join-Path $repo 'ArenaMode.Client/Areas/ArenaAreaNavigationPatches.cs');Property='AreaPatchSource';Find='if (ArenaAreaTranslocatorGate.TryResolve(__instance, __0, out bool translocatorAllowed)) return translocatorAllowed;';Replace=';';Failure='supported ground air and roof relocation succeeds without bot navigation'},
    @{Name='invalid-ticket-falls-through';Path=$gate;Property='GateSource';Find="allowed = TryConsume(player, target);`n        return true;";Replace="allowed = TryConsume(player, target);`n        return allowed;";Failure='changed world body controller area disc and target deny the owned native call including whole maps keeps body in place'},
    @{Name='reusable-authorization';Path=$gate;Property='GateSource';Find='ticket != null && !ticket.Consumed && ReferenceEquals(_current, ticket)';Replace='ticket != null && ReferenceEquals(_current, ticket)';Failure='same target cannot reuse consumed authorization'},
    @{Name='foreign-world-ticket';Path=$gate;Property='GateSource';Find='&& ReferenceEquals(ticket.World, Singleton<GameWorld>.Instance)';Replace='';Failure='changed world body controller area disc and target deny the owned native call including whole maps keeps body in place'},
    @{Name='foreign-context-ticket';Path=$gate;Property='GateSource';Find='&& ReferenceEquals(ticket.Context, player.MovementContext)';Replace='';Failure='changed world body controller area disc and target deny the owned native call including whole maps keeps body in place'},
    @{Name='changed-native-target';Path=$gate;Property='GateSource';Find='&& ArenaTranslocatorTeleportPolicy.Exact(ticket.Target, target)';Replace='';Failure='changed world body controller area disc and target deny the owned native call including whole maps keeps body in place'},
    @{Name='forgot-authorization-disposal';Path=$teleport;Property='TeleportSource';Find='finally { ticket?.Dispose(); _executing = false; }';Replace='finally { _executing = false; }';Failure='supported ground air and roof relocation succeeds without bot navigation'},
    @{Name='false-success-without-prefix';Path=$teleport;Property='TeleportSource';Find='if (!ticket.Consumed || !ArenaTranslocatorTeleportPolicy.Arrived(actual, target)';Replace='if (!ArenaTranslocatorTeleportPolicy.Arrived(actual, target)';Failure='native refusal exception target ownership and readback control success'},
    @{Name='missing-readback';Path=$teleport;Property='TeleportSource';Find='if (!ticket.Consumed || !ArenaTranslocatorTeleportPolicy.Arrived(actual, target)';Replace='if (!ticket.Consumed';Failure='native refusal exception target ownership and readback control success'},
    @{Name='lost-disc-after-native';Path=$teleport;Property='TeleportSource';Find="if (!ticket.Consumed || !ArenaTranslocatorTeleportPolicy.Arrived(actual, target)`n                || !ArenaTranslocatorRuntime.IsOwnedDestination(player, target))";Replace='if (!ticket.Consumed || !ArenaTranslocatorTeleportPolicy.Arrived(actual, target))';Failure='native refusal exception target ownership and readback control success'},
    @{Name='saturated-query-trusted';Path=$teleport;Property='TeleportSource';Find='if (count >= Neighbours.Length) return false;';Replace='if (count > Neighbours.Length) return false;';Failure='saturated overlap query is not clearance'},
    @{Name='stale-door-query';Path=$teleport;Property='TeleportSource';Find='Physics.SyncTransforms(); // Explicit click: a door moved this frame must already block admission.';Replace=';';Failure='moved door synchronized before collision proof'},
    @{Name='stale-native-contact';Path=$teleport;Property='TeleportSource';Find='controller.isGrounded = false;';Replace=';';Failure='native momentum freefall and new unsupported contact are preserved'},
    @{Name='missing-native-contact-query';Path=$teleport;Property='TeleportSource';Find='_context.UpdateGroundCollision(0f);';Replace=';';Failure='fresh native ground query invalidates old contact before return'},
    @{Name='unsynchronized-contact-query';Path=$teleport;Property='TeleportSource';Find="Physics.SyncTransforms();`n            if (!IsCurrent()) return false;";Replace='if (!IsCurrent()) return false;';Failure='fresh native ground query invalidates old contact before return'},
    @{Name='fabricated-unsupported-ground';Path=$teleport;Property='TeleportSource';Find='_context.UpdateGroundCollision(0f);';Replace='_context.UpdateGroundCollision(0f); _context.IsGrounded = false;';Failure='fresh real support is retained by the native ground query'},
    @{Name='invented-falling-time';Path=$teleport;Property='TeleportSource';Find='_context.UpdateGroundCollision(0f);';Replace='_context.UpdateGroundCollision(0f); _context.FreefallTime = 0;';Failure='native momentum freefall and new unsupported contact are preserved'},
    @{Name='contact-callback-owner-loss';Path=$teleport;Property='TeleportSource';Find='return IsBodyCurrent();';Replace='return true;';Failure='native contact callbacks keep identity and position confirmation exact'},
    @{Name='contact-callback-position-loss';Path=$teleport;Property='TeleportSource';Find='                actual = player.Position;';Replace=';';Failure='native contact callbacks keep identity and position confirmation exact'},
    @{Name='contact-sync-owner-loss';Path=$teleport;Property='TeleportSource';Find='if (!IsCurrent()) return false;';Replace=';';Failure='changed owner during transform synchronization cannot refresh a stale context'},
    @{Name='contact-query-retains-context-support';Path=$teleport;Property='TeleportSource';Find='_context.IsGrounded = false;';Replace=';';Failure='failed native ground query cannot retain old physical ground contact'},
    @{Name='missing-actor-occupancy';Path=$teleport;Property='TeleportSource';Find='if (!ClearActors(world, player, capsule, delta))';Replace='if (false)';Failure='living trigger hurt volume blocks occupancy without telefrag'},
    @{Name='missing-extra-shape';Path=$teleport;Property='TeleportSource';Find='&& !ClearSolid(player, collider, delta, controller._collisionMask.value))';Replace='&& false)';Failure='additional controller shape must clear the ceiling'},
    @{Name='capsule-radius-outside-area';Path=$gate;Property='GateSource';Find='float inset = radius + ArenaAreaCatalog.NavigationInset;';Replace='float inset = ArenaAreaCatalog.NavigationInset;';Failure='full capsule radius respects area inset'},
    @{Name='capsule-head-outside-area';Path=$gate;Property='GateSource';Find='&& area.Bounds.Contains(top.x, top.y + radius, top.z, inset)';Replace='';Failure='full capsule head respects area ceiling'},
    @{Name='capsule-crosses-concavity';Path=$gate;Property='GateSource';Find="&& area.Bounds.ContainsPath(new ArenaAreaPoint(bottom.x, bottom.y, bottom.z),`n                new[] { new ArenaAreaPoint(top.x, top.y, top.z) }, true, inset)";Replace='';Failure='rotated capsule cannot bridge concave area gap'},
    @{Name='old-jump-potential-launches-body';Path=$teleport;Property='TeleportSource';Find='jump._potentialH += delta.y;';Replace=';';Failure='jump and fall potential heights rebased without false lift'},
    @{Name='old-native-destination';Path=$teleport;Property='TeleportSource';Find='if (_state.Destination.HasValue) _state.Destination += delta;';Replace=';';Failure='native destination history rebased'},
    @{Name='old-context-height';Path=$teleport;Property='TeleportSource';Find='if (_context._hasLastHeight) _context._lastPlayerHeight += delta.y;';Replace=';';Failure='context height history rebased'},
    @{Name='jump-credit-replenished';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaDoubleJump.cs');Property='DoubleJumpSource';Find='if (credit != null) { unchecked { credit.StateRevision++; } CancelNativeRequest(credit); }';Replace='if (credit != null) { unchecked { credit.StateRevision++; } credit.Spent = false; CancelNativeRequest(credit); }';Failure='jump requests cancelled without granting credit'},
    @{Name='stale-bunnyhop-buffer';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaBunnyhop.cs');Property='BunnySource';Find='LaunchY = flight.LaunchY + delta.y, LeftGround = flight.LeftGround, Hops = flight.Hops';Replace='LaunchY = flight.LaunchY + delta.y, LeftGround = flight.LeftGround, Hops = flight.Hops, BufferedAt = flight.BufferedAt';Failure='old positional contact slide and mantle observations cancelled'},
    @{Name='lost-bunnyhop-carry';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaBunnyhop.cs');Property='BunnySource';Find='Carry = flight.Carry, HasCarry = flight.HasCarry';Replace='Carry = flight.Carry, HasCarry = false';Failure='applied airborne carry and steered heading preserved'},
    @{Name='old-bunnyhop-launch-floor';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaBunnyhop.cs');Property='BunnySource';Find='LaunchY = flight.LaunchY + delta.y';Replace='LaunchY = flight.LaunchY';Failure='bunnyhop launch height rebased and old motion witness retired'},
    @{Name='lost-air-control-heading';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaAirControl.cs');Property='AirSource';Find='flight.InputState = null;';Replace='flight.InputState = null; flight.HasHeading = false;';Failure='applied airborne carry and steered heading preserved'},
    @{Name='slide-component-disabled';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaSlideTransitions.cs');Property='SlideSource';Find="_slide.Clear();`n        _sampling = _contact = false;";Replace="_slide.Clear(); _slide.enabled = false;`n        _sampling = _contact = false;";Failure='slide component remains available after relocation'},
    @{Name='old-mantle-observation';Path=(Join-Path $repo 'ArenaMode.Client/Movement/ArenaAirVault.cs');Property='VaultSource';Find='if (ReferenceEquals(_motionObservation?.Request?.Player, player)) _motionObservation = null;';Replace=';';Failure='old positional contact slide and mantle observations cancelled'}
)
Test-ArenaSourceFaults -Project (Join-Path $PSScriptRoot 'TranslocatorTeleportChecks.csproj') -Token 'TRANSLOCATOR_TELEPORT_CHECKS_PASSED' -Faults $faults -RequireSingleSite
& (Join-Path $PSScriptRoot 'Verify-NativeContract.ps1')
if($LASTEXITCODE -ne 0){throw 'Native contract check failed'}
Write-Output 'TRANSLOCATOR_TELEPORT_CHECKS_PASSED full linked production, extracted integrations and native contract'
